<section class="dashboard-shell"><div class="container"><div class="dashboard-head"><div><span class="eyebrow"><span></span> الإدارة</span><h1>المستخدمون</h1><p>مراجعة حسابات المديرين والأطباء والمرضى وحالتها.</p></div></div><details class="booking-panel"><summary><span>＋</span><div><strong>إضافة حساب</strong><small>إنشاء طبيب أو مدير أو مريض</small></div></summary><form method="post" action="<?= url('/users') ?>" class="form-grid booking-form"><?= csrf_field() ?><label>الاسم<input name="name" required minlength="3" maxlength="120"></label><label>الدور<select name="role" required><option value="doctor">طبيب</option><option value="patient">مريض</option><option value="admin">مدير</option></select></label><label>البريد<input type="email" name="email" required></label><label>رقم الجوال<input type="tel" name="phone" placeholder="05xxxxxxxx" required></label><label>التخصص <small>(للطبيب)</small><input name="specialty" maxlength="120"></label><label>كلمة مرور مؤقتة<input type="password" name="password" minlength="10" required></label><button class="button button-primary" type="submit">إنشاء الحساب</button></form></details><section class="panel"><div class="panel-title"><div><h2>كل الحسابات</h2><p><?= count($users) ?> حسابًا مسجلًا</p></div></div><div class="table-wrap"><table><thead><tr><th>المستخدم</th><th>الدور</th><th>التواصل</th><th>الحالة</th><th></th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><strong><?= e($user['name']) ?></strong><small><?= e($user['specialty'] ?? 'منضم منذ ' . date('Y/m/d', strtotime($user['created_at']))) ?></small></td><td><span class="role-badge role-<?= e($user['role']) ?>"><?= e(role_label($user['role'])) ?></span></td><td><?= e($user['email']) ?><small><?= e($user['phone']) ?></small></td><td><span class="status <?= $user['is_active'] ? 'status-confirmed' : 'status-cancelled' ?>"><?= $user['is_active'] ? 'نشط' : 'معطل' ?></span></td><td><form method="post" action="<?= url('/users/' . $user['id'] . '/toggle') ?>"><?= csrf_field() ?><button class="button button-ghost button-small" type="submit"><?= $user['is_active'] ? 'تعطيل' : 'تفعيل' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div></section>
